<?php
session_start(); require_once __DIR__.'/../autenticacao.php'; require_once __DIR__.'/conexaoDB.php'; require_once __DIR__.'/../cabecalho.php'; require_once __DIR__.'/../includes/auditoria.php'; exigirLogin('gerente');
if($_SERVER['REQUEST_METHOD']==='POST'){ $nome=trim($_POST['nome']??''); if($nome!==''){ $stmt=mysqli_prepare($conexao,'INSERT INTO categorias (nome) VALUES (?)'); mysqli_stmt_bind_param($stmt,'s',$nome); if(mysqli_stmt_execute($stmt)){registrarAuditoria($conexao,'cadastrar','categoria',mysqli_insert_id($conexao),'Categoria '.$nome.' cadastrada');header('Location: categorias.php?ok=1');exit;} } header('Location: categorias.php?erro=1');exit; }
if(isset($_GET['id'],$_GET['status'])){ $id=(int)$_GET['id'];$ativo=$_GET['status']==='ativar'?1:0;$stmt=mysqli_prepare($conexao,'UPDATE categorias SET ativo=? WHERE id=?');mysqli_stmt_bind_param($stmt,'ii',$ativo,$id);mysqli_stmt_execute($stmt);header('Location: categorias.php');exit; }
$categorias=mysqli_query($conexao,'SELECT c.*,COUNT(p.id) produtos FROM categorias c LEFT JOIN produtos p ON p.categoria_id=c.id GROUP BY c.id ORDER BY c.nome');
?>
<!DOCTYPE html><html lang="pt-BR"><head><?php recursosCabeca('Categorias'); ?></head><body><?php cabecalho('FarmaCerta - Gerente','gerente','produtos'); ?><main class="container py-4"><section class="card card-brand rounded-4 p-4 mb-4"><h2 class="h3 fw-bold">CATEGORIAS DE PRODUTOS</h2><p class="mb-0">Organize medicamentos, higiene, cosméticos e outras linhas.</p></section><?php if(isset($_GET['ok'])){?><div class="alert alert-success">Categoria cadastrada.</div><?php } if(isset($_GET['erro'])){?><div class="alert alert-danger">Não foi possível cadastrar. Talvez o nome já exista.</div><?php } ?><section class="card shadow-sm rounded-4 p-4 mb-4"><form method="POST" class="row g-3"><div class="col-md-8"><label class="form-label">Nome da categoria</label><input class="form-control" name="nome" required></div><div class="col-md-4 d-flex align-items-end"><button class="btn btn-primary rounded-pill">CADASTRAR</button></div></form></section><section class="card shadow-sm rounded-4 p-3"><table class="table table-hover"><thead><tr><th>Categoria</th><th>Produtos</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php while($c=mysqli_fetch_assoc($categorias)){?><tr><td><?php echo htmlspecialchars($c['nome']); ?></td><td><?php echo (int)$c['produtos']; ?></td><td><?php echo $c['ativo']?'Ativa':'Inativa'; ?></td><td><a class="btn btn-sm btn-outline-primary rounded-pill" href="categorias.php?id=<?php echo $c['id']; ?>&status=<?php echo $c['ativo']?'desativar':'ativar'; ?>"><?php echo $c['ativo']?'DESATIVAR':'ATIVAR'; ?></a></td></tr><?php } ?></tbody></table></section></main><?php recursosRodape(); ?></body></html>